const apiKeyInput=document.getElementById("apiKey"),saveBtn=document.getElementById("saveBtn"),statusMsg=document.getElementById("statusMsg"),currentStatus=document.getElementById("currentStatus");chrome.storage.local.get("nvidiaApiKey",t=>{t.nvidiaApiKey?(apiKeyInput.value=t.nvidiaApiKey,currentStatus.innerHTML='<span class="status-badge active">API Key Set</span>'):currentStatus.innerHTML='<span class="status-badge inactive">No API Key</span>'}),saveBtn.addEventListener("click",()=>{const t=apiKeyInput.value.trim();if(!t)return statusMsg.textContent="Please enter an API key",void(statusMsg.className="status error");chrome.storage.local.set({nvidiaApiKey:t},()=>{statusMsg.textContent="Saved! Astra is ready to teach.",statusMsg.className="status success",currentStatus.innerHTML='<span class="status-badge active">API Key Set</span>',setTimeout(()=>{statusMsg.textContent=""},3e3)})});